  api('dashboard/?'+query(client,defaultFilters,{lag_date:lagDate}),{token,signal:controller.signal})
   .then(data=>{if(active)setStats(data)}).catch(e=>{if(active&&e.name!=='AbortError')setStatsError(e.message)}).finally(()=>{if(active)setStatsLoading(false)});
