  if(JSON.stringify(debouncedFilters)!==serialized){setRows([]);return}
  for(const prefix of ['tpa','total']){const min=debouncedFilters[prefix+'Min'],max=debouncedFilters[prefix+'Max'];if((min!==''&&(!/^\d+$/.test(min)))||(max!==''&&(!/^\d+$/.test(max)))||(min!==''&&max!==''&&Number(min)>Number(max))){setRows([]);setClaimsError('Enter nonnegative whole ages with minimum no greater than maximum.');return}}
