function SettingsPage({token,onLogout,client}){const [current,setCurrent]=useState(''),[next,setNext]=useState(''),[confirm,setConfirm]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function save(e){e.preventDefault();setBusy(true);setError('');try{await api('auth/change-password/',{token,method:'POST',body:{current_password:current,new_password:next,confirm_password:confirm}});onLogout()}catch(e){setError(e.message)}finally{setBusy(false)}}return <><Header title="Settings" subtitle="Manage account security and workspace access."/><div className="settings-grid"><FolderConfiguration client={client} token={token}/><FolderRules client={client} token={token}/><FolderProcessing client={client} token={token}/><section className="surface settings-panel"><span className="eyebrow">ACCOUNT SECURITY</span><h3>Change password</h3><p>For security, changing your password signs you out on this device.</p><form onSubmit={save} className="password-form"><label>Current password<input type="password" value={current} onChange={e=>setCurrent(e.target.value)} required/></label><label>New password<input type="password" value={next} onChange={e=>setNext(e.target.value)} required minLength={8}/></label><label>Confirm new password<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} required minLength={8}/></label>{error&&<p className="errorline">{error}</p>}<button className="btn primary" disabled={busy}>Update password</button></form></section></div></>}
function UserManagement({token}) {
 const [users,setUsers]=useState([]),[username,setUsername]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState('');
 const [error,setError]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 const [action,setAction]=useState(null),[newPassword,setNewPassword]=useState(''),[confirmPassword,setConfirmPassword]=useState(''),[confirmUsername,setConfirmUsername]=useState('');
 const reload=useCallback(()=>api('users/superusers/',{token}).then(d=>setUsers(d.users||[])).catch(e=>setError(e.message)),[token]);
 useEffect(()=>{reload()},[reload]);
 async function create(e){e.preventDefault();setError('');setMessage('');setBusy(true);try{await api('users/superusers/',{token,method:'POST',body:{username,email,password}});setUsername('');setEmail('');setPassword('');setMessage('Super user created.');await reload()}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function toggle(u){setError('');setMessage('');try{await api('users/superusers/',{token,method:'PATCH',body:{id:u.id,active:!u.active}});await reload()}catch(e){setError(e.message)}}
 function openAction(type,user){setAction({type,user});setNewPassword('');setConfirmPassword('');setConfirmUsername('');setError('');setMessage('')}
 async function submitAction(e){e.preventDefault();if(!action)return;setError('');setMessage('');setBusy(true);try{if(action.type==='password'){await api('users/superusers/password/',{token,method:'POST',body:{id:action.user.id,new_password:newPassword,confirm_password:confirmPassword}});setMessage('Password changed. Previous login token revoked.')}else{await api('users/superusers/delete/',{token,method:'POST',body:{id:action.user.id,confirm_username:confirmUsername}});setMessage('Super user deleted.')}setAction(null);await reload()}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <><Header title="User management" subtitle="Create and manage super users. All super users access the same live clients."/>
 {error&&<p className="errorline" role="alert">{error}</p>}{message&&<p role="status">{message}</p>}
 <section className="surface settings-panel"><h3>Create super user</h3><form onSubmit={create} className="password-form"><label>Username<input value={username} onChange={e=>setUsername(e.target.value)} required/></label><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Initial password<input type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} required/></label><button className="btn primary" disabled={busy}>Create super user</button></form></section>
 <section className="surface settings-panel" style={{marginTop:16}}><h3>Super user accounts</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>USERNAME</th><th>EMAIL</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.username}</td><td>{u.email}</td><td>{u.active?'Active':'Disabled'}</td><td><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><button className="btn tiny" disabled={busy} onClick={()=>toggle(u)}>{u.active?'Disable':'Enable'}</button><button className="btn tiny" disabled={busy} onClick={()=>openAction('password',u)}>Change password</button><button className="btn tiny" disabled={busy} onClick={()=>openAction('delete',u)} style={{color:'#b42318'}}>Delete</button></div></td></tr>)}</tbody></table></div></section>
 {action&&<Modal title={action.type==='password'?'Change super user password':'Delete super user'} subtitle={action.user.username} onClose={()=>!busy&&setAction(null)}><form onSubmit={submitAction} className="password-form" style={{padding:18}}>
 {action.type==='password'?<><label>New password<input type="password" autoComplete="new-password" minLength={8} value={newPassword} onChange={e=>setNewPassword(e.target.value)} required/></label><label>Confirm new password<input type="password" autoComplete="new-password" minLength={8} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} required/></label></>:<><p>This permanently removes the account. Claims and RECON records are not removed. Protected historical records may prevent deletion.</p><label>Type username to confirm<input autoComplete="off" value={confirmUsername} onChange={e=>setConfirmUsername(e.target.value)} required placeholder={action.user.username}/></label></>}
 <div style={{display:'flex',gap:8,justifyContent:'flex-end',marginTop:12}}><button className="btn" type="button" disabled={busy} onClick={()=>setAction(null)}>Cancel</button><button className="btn primary" type="submit" disabled={busy||(action.type==='delete'&&confirmUsername!==action.user.username)||(action.type==='password'&&(!newPassword||newPassword!==confirmPassword))}>{busy?'Saving…':action.type==='password'?'Save password':'Delete user'}</button></div></form></Modal>}
 </>;
}
